'use strict';
const slots=['ATT','MID','MID','DEF','GK'];
const pools=window.HBW_DATA.pools;
let selectedMode='current';
const modeNames={current:'Current Players',prime:'All-Time Players'};
function playerPool(){return pools[selectedMode];}
function shuffle(a){a=[...a];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
function makeDeck(){return shuffle(playerPool());}
// Keepers have twice the draw weight; neither team is guaranteed one.
function drawPlayer(available){const total=available.reduce((n,p)=>n+(p.pos==='GK'?2:1),0);let ticket=Math.random()*total;for(const p of available){ticket-=p.pos==='GK'?2:1;if(ticket<0)return p;}return available[available.length-1];}
function fitScore(p,slot){if((p.positions||[p.pos]).includes(slot))return p.rating;if(slot==='GK')return p.gkScore;if(p.pos==='GK')return Math.round(p.rating*.35);return Math.round(p.rating*(p.pos==='MID'||slot==='MID'?.8:.6));}
// At most 120 assignments. All five positions are always considered.
function bestLineup(squad){let best={total:-1,rows:Array(5).fill(null)};function visit(index,rows,total){if(index===squad.length){if(total>best.total)best={total,rows:[...rows]};return;}const signing=squad[index];for(let i=0;i<5;i++){if(rows[i])continue;rows[i]={...signing,slot:slots[i],score:fitScore(signing.player,slots[i])};visit(index+1,rows,total+rows[i].score);rows[i]=null;}}visit(0,Array(5).fill(null),0);best.rating=best.total/5;return best;}
let lastCardKey=null;
let state,spinTimer,spinInterval,spinResolve,epoch=0,tossTimer,tossResolve;
const $=id=>document.getElementById(id);
function reset(mode=selectedMode){if(!['current','prime'].includes(mode))throw Error('Unknown game mode.');selectedMode=mode;epoch++;clearTimeout(tossTimer);if(tossResolve){tossResolve({cancelled:true});tossResolve=null;}clearTimeout(spinTimer);clearInterval(spinInterval);if(spinResolve){spinResolve({cancelled:true});spinResolve=null;}state={teams:[{money:20,squad:[]},{money:20,squad:[]}],mode:selectedMode,deck:makeDeck(),phase:'toss-ready',firstBidder:null,lot:0,current:null,bid:0,leader:null,turn:0,passed:[false,false],message:'A 50/50 toss decides who opens the first auction.'};$('results').hidden=true;render();}
function maxBid(t){const team=state.teams[t];return team.squad.length===5?0:team.money;}
function active(t){return state.teams[t].squad.length<5&&state.teams[t].money>0&&!state.passed[t];}
function soloAuction(t){const opponent=state.teams[1-t];return state.bid===0&&(opponent.money===0||opponent.squad.length===5);}
function canPass(t){return true;}
function card(p,spinning=false){return `<div class="player-card ${p.kind==='Legend'?'legend-card':''} ${spinning?'spinning':'revealed'}"><div class="card-top"><span><span class="card-rating">${p.rating}</span><br><span class="card-position">${p.pos}</span></span><span>${p.kind==='Season'?'CURRENT':p.kind==='Legend'?'LEGEND':'ALL-TIME'}</span></div><div class="player-monogram" aria-hidden="true">${p.name.split(' ').map(n=>n[0]).slice(0,2).join('')}</div><div class="card-name">${p.name}</div><div class="card-meta">${p.country} · ${p.positions.join(' / ')}</div><div class="card-stats">${p.labels.map((label,i)=>`<span><b>${p.stats[i]}</b>${label}</span>`).join('')}</div><span class="card-source">${p.kind==='Legend'?'LEGEND':p.kind==='Prime'?'ALL-TIME PLAYER':'SEASON CARD'}</span></div>`;}
function spotlight(){if(state.phase==='bidding')return state.turn;if(['free-ready','free-spinning'].includes(state.phase))return state.freeTurn;if(state.phase==='ready'&&state.lot===0)return state.firstBidder;return null;}
function renderTeams(){for(let t=0;t<2;t++){const team=state.teams[t],lineup=bestLineup(team.squad);$('team-'+t).classList.toggle('active-turn',spotlight()===t);$('team-'+t).setAttribute('aria-label',`Player ${t+1}${spotlight()===t?' — active player':''}`);$('team-'+t).innerHTML=`<div class="team-head"><div class="manager-number">0${t+1}</div><div class="team-title"><h2>PLAYER ${t+1}</h2><small>${t?'The challenger':'The home side'}</small></div><span class="team-tag">${team.squad.length===5?'FULL SQUAD':spotlight()===t?(state.phase==='bidding'?'YOUR BID':'YOUR TURN'):team.money===0?'WAITING':'READY'}</span></div><div class="budget-area"><div><div class="tiny-label">BUDGET LEFT</div><div class="budget">$${team.money}<small>/ $20</small></div></div></div><div class="roster-heading"><span>YOUR STARTING FIVE</span><span>${team.squad.length} / 5</span></div><div class="roster">${lineup.rows.map((r,i)=>r?`<div class="roster-row"><span class="slot-label">${slots[i]}</span><span class="roster-name">${r.player.name}<small>${r.price===0?'FREE PICK':'$'+r.price} · ${r.player.pos}${!(r.player.positions||[r.player.pos]).includes(slots[i])?` → ${slots[i]} · −${r.player.rating-r.score}`:''}</small></span><span class="roster-score ${!(r.player.positions||[r.player.pos]).includes(slots[i])?'penalty':''}">${r.score}</span></div>`:`<div class="roster-row empty"><span class="slot-label">${slots[i]}</span><span class="roster-name">Open position</span><span>+</span></div>`).join('')}</div><div class="team-total"><span>ADJUSTED TEAM RATING</span><strong>${team.squad.length?lineup.rating.toFixed(1):'—'}</strong></div>`;}}
function render(){if(!state.current)lastCardKey=null;renderTeams();const signed=state.teams.reduce((n,t)=>n+t.squad.length,0);$('progress').innerHTML=Array.from({length:10},(_,i)=>`<span class="${i<signed?'filled':''}"></span>`).join('');$('progress').setAttribute('aria-label',`${signed} of 10 players signed`);$('signed-count').textContent=`${signed} / 10 SIGNED`;$('phase-title').textContent=state.phase==='done'?'The final whistle':'Build your five';$('lot').textContent=state.lot?`AUCTION ${String(state.lot).padStart(2,'0')}`:'AUCTION FLOOR';$('stage').textContent=({'toss-ready':'WHO GOES FIRST?',tossing:'FLIPPING…',ready:'READY TO SPIN',spinning:'SCOUTING…',bidding:'BIDDING OPEN',sold:'DEAL DONE',unsold:'UNSOLD','free-ready':'FREE PICK ROUND','free-spinning':'REVEALING FREE PICK…',done:'SQUADS COMPLETE'})[state.phase];$('announcement').textContent=state.message;document.querySelector('.auction').setAttribute('data-player',spotlight()===null?'':String(spotlight()+1));
if(state.phase==='toss-ready'||state.phase==='tossing'){$('card-zone').innerHTML=`<div class="toss-area"><div class="toss-coin ${state.phase==='tossing'?'flipping':''}"><span>1</span><i>/</i><span>2</span></div><h2>Who bids first?</h2><p>One fair toss. A 50/50 chance.</p></div>`;}else if(state.phase==='ready'&&state.lot===0){$('card-zone').innerHTML=`<div class="toss-area toss-winner p${state.firstBidder+1}"><div class="toss-coin">${state.firstBidder+1}</div><h2>PLAYER ${state.firstBidder+1} WINS!</h2><p>You have the first bid.</p></div>`;}else if(state.current){const spinning=['spinning','free-spinning'].includes(state.phase),key=state.current.id+':'+spinning;if(key!==lastCardKey){$('card-zone').innerHTML=card(state.current,spinning);lastCardKey=key;}}else{$('card-zone').innerHTML=`<div class="player-card mystery"><div class="question">?</div><div class="card-name">YOUR NEXT SIGNING</div><div class="card-meta">${selectedMode==='prime'?'STARS · CULT HEROES':'STARS · FAN FAVOURITES'}</div></div>`;}
if(['toss-ready','tossing'].includes(state.phase)){$('auction-controls').innerHTML=`<button class="primary" id="toss" ${state.phase==='tossing'?'disabled':''}>${state.phase==='tossing'?'Flipping the coin…':'Toss for first bid ↻'}</button><p class="control-hint">The opening turn alternates after each auction.</p>`;$('toss').onclick=toss;}else if(state.phase==='bidding'){const allowed=maxBid(state.turn)>=state.bid+1,solo=soloAuction(state.turn);$('auction-controls').innerHTML=`<div class="bid-top"><div><small>${state.bid?'CURRENT BID':'OPENING BID'}</small><strong>$${state.bid||1}</strong></div><div class="turn-label p${state.turn+1}"><b>Player ${state.turn+1}’s turn</b><small>${state.leader===null?'Be the first to bid':`Player ${state.leader+1} is leading`}</small></div></div><div class="bid-buttons"><button class="primary" id="bid" ${allowed?'':'disabled'}>${state.bid?`Raise to $${state.bid+1}`:solo?'Sign for $1':'Open at $1'} ↑</button><button class="quiet" id="pass" ${canPass(state.turn)?'':'disabled'}>Pass</button></div><button class="all-in text-button" id="all-in" ${allowed?'':'disabled'}>All in · $${maxBid(state.turn)}</button><p class="control-hint">${allowed?`Bid up to $${maxBid(state.turn)}, or pass. Passes are unlimited.`:'You cannot raise this bid. Pass to finish the auction.'}</p>`;$('bid').onclick=()=>bid(state.turn);$('pass').onclick=()=>pass(state.turn);if($('all-in'))$('all-in').onclick=()=>bid(state.turn,maxBid(state.turn));
}else if(['free-ready','free-spinning'].includes(state.phase)){$('auction-controls').innerHTML=`<div class="free-turn">PLAYER ${state.freeTurn+1} · FREE PICK ${state.teams[state.freeTurn].squad.length+1} / 5</div><button class="primary" id="spin" ${state.phase==='free-spinning'?'disabled':''}>${state.phase==='free-spinning'?'Revealing your free signing…':'Spin one free signing ↻'}</button><p class="control-hint">This random signing is yours. No bidding or skipping.</p>`;$('spin').onclick=spin;}else if(state.phase==='done'){$('auction-controls').innerHTML='<button class="primary" id="show-results">See the winning squad <span class="arrow">↓</span></button>';$('show-results').onclick=()=>showResults();
}else{$('auction-controls').innerHTML=`<button class="primary" id="spin" ${state.phase==='spinning'?'disabled':''}>${state.phase==='spinning'?'Finding your next signing…':state.lot?'Spin the next footballer':'Spin a footballer'} <span class="arrow">↻</span></button><p class="control-hint">${state.lot?'Choose carefully. Five signings are final.':'Reveal first. Then let the bidding begin.'}</p>`;$('spin').onclick=spin;}}
function toss(){if(state.phase!=='toss-ready'||!$('home').hidden)throw Error('Start a game before tossing.');state.phase='tossing';state.firstBidder=Math.random()<.5?0:1;state.message='Heads for Player 1. Tails for Player 2.';render();const run=epoch;return new Promise(resolve=>{tossResolve=resolve;tossTimer=setTimeout(()=>{tossResolve=null;if(run!==epoch){resolve({cancelled:true});return;}state.phase='ready';state.message=`Player ${state.firstBidder+1} won the toss and bids first. Spin to reveal the footballer.`;render();resolve(readState());},window.matchMedia('(prefers-reduced-motion: reduce)').matches?80:1600);});}
function spin(){if(!$('home').hidden)throw Error('Choose a mode and start a game first.');if(state.phase==='free-ready')return spinFree();if(!['ready','sold','unsold'].includes(state.phase))throw Error('Finish the current auction first.');if(!state.deck.length){const signed=new Set(state.teams.flatMap(t=>t.squad.map(s=>s.player.id)));state.deck=shuffle(playerPool().filter(p=>!signed.has(p.id)));}const chosen=drawPlayer(state.deck);state.deck=state.deck.filter(p=>p.id!==chosen.id);state.phase='spinning';state.current=chosen;state.lot++;state.bid=0;state.leader=null;state.passed=[false,false];state.message='Scouting the stars. Who’s coming out next?';render();const run=epoch,reduced=window.matchMedia('(prefers-reduced-motion: reduce)').matches;return new Promise(resolve=>{spinResolve=resolve;if(!reduced)spinInterval=setInterval(()=>{$('card-zone').innerHTML=card(playerPool()[Math.floor(Math.random()*playerPool().length)],true)},100);spinTimer=setTimeout(()=>{clearInterval(spinInterval);spinResolve=null;if(run!==epoch){resolve({cancelled:true});return;}state.phase='bidding';state.turn=(state.firstBidder+state.lot-1)%2;if(!active(state.turn))state.turn=1-state.turn;state.message=`${chosen.name} is on the market. Let the bidding begin.`;render();resolve(readState());},reduced?100:1800);});}
function assertTurn(t){if(state.phase!=='bidding'||!Number.isInteger(t)||t!==state.turn||!active(t))throw Error('It is not this player’s bidding turn.');}
function bid(t,amount=state.bid+1){assertTurn(t);if(!Number.isInteger(amount)||amount<=state.bid)throw Error('Bid must be a whole dollar above the current bid.');if(amount>maxBid(t))throw Error('Bid exceeds your available budget.');state.bid=amount;state.leader=t;const opponent=1-t;if(!active(opponent)){award();return readState();}state.turn=opponent;state.message=`Player ${t+1} bids $${amount} for ${state.current.name}.`;render();return readState();}
function pass(t){assertTurn(t);state.passed[t]=true;if(state.leader!==null){award();return readState();}const other=1-t;if(active(other)){state.turn=other;state.message=`Player ${t+1} passes. Player ${other+1}, open at $1 or pass.`;}else{state.phase='unsold';state.message=`No bids for ${state.current.name}. Spin again for a new footballer.`;}render();return readState();}
function nextPhase(){if(state.teams.every(t=>t.squad.length===5)){state.phase='done';return;}if(state.teams.some(t=>t.money>0&&t.squad.length<5)){state.phase='sold';return;}state.phase='free-ready';state.freeTurn=state.teams.findIndex(t=>t.squad.length<5);}
function award(){const t=state.leader;state.teams[t].money-=state.bid;state.teams[t].squad.push({player:state.current,price:state.bid});nextPhase();state.message=`SOLD! ${state.current.name} joins Player ${t+1} for $${state.bid}.`+(state.teams[t].money===0&&state.teams[t].squad.length<5?' Budget spent. Your remaining signings will spin one by one after paid bidding ends.':'');if(state.phase==='free-ready')state.message+=' Paid bidding is over. Time for the free-pick round!';render();if(state.phase==='done')showResults(false);}
function spinFree(){const t=state.freeTurn;const claimed=new Set(state.teams.flatMap(t=>t.squad.map(s=>s.player.id)));const available=playerPool().filter(p=>!claimed.has(p.id));const chosen=drawPlayer(available);state.phase='free-spinning';state.current=chosen;state.message=`Player ${t+1}, this next free signing is yours.`;render();const run=epoch,reduced=window.matchMedia('(prefers-reduced-motion: reduce)').matches;return new Promise(resolve=>{spinResolve=resolve;if(!reduced)spinInterval=setInterval(()=>{$('card-zone').innerHTML=card(available[Math.floor(Math.random()*available.length)],true)},100);spinTimer=setTimeout(()=>{clearInterval(spinInterval);spinResolve=null;if(run!==epoch){resolve({cancelled:true});return;}state.teams[t].squad.push({player:chosen,price:0});state.deck=state.deck.filter(p=>p.id!==chosen.id);nextPhase();state.message=`FREE SIGNING! ${chosen.name} joins Player ${t+1}.`+(state.phase==='free-ready'?` Player ${state.freeTurn+1}, spin your next free pick.`:' Both squads are complete!');render();if(state.phase==='done')showResults(false);resolve(readState());},reduced?100:1800);});}
function showResults(scroll=true){if(state.phase!=='done')throw Error('Both squads need five players.');const scores=state.teams.map(t=>bestLineup(t.squad)),difference=Math.abs(scores[0].total-scores[1].total)/5,winner=scores[0].total===scores[1].total?null:scores[0].total>scores[1].total?0:1;const lost=state.teams.map((t,i)=>t.squad.reduce((n,s)=>n+s.player.rating,0)-scores[i].total);$('results').innerHTML=`<div class="result-panel"><div class="eyebrow">HIGHEST RATING TAKES THE GLORY</div><h2>${winner===null?'IT’S A DRAW!':`PLAYER ${winner+1} WINS!`}</h2><p class="result-note">${winner===null?'Two equally matched squads. Same adjusted rating, shared bragging rights.':`${difference.toFixed(1)} rating points made the difference. Your best possible lineups are shown above.`}</p><div class="result-scores"><div><div class="tiny-label">PLAYER 1</div><strong style="color:var(--blue)">${scores[0].rating.toFixed(1)}</strong><small>Adjusted team rating</small></div><span class="tiny-label">VS</span><div><div class="tiny-label">PLAYER 2</div><strong style="color:var(--orange)">${scores[1].rating.toFixed(1)}</strong><small>Adjusted team rating</small></div></div><div class="result-detail">${lost.map((n,i)=>`<span>Player ${i+1}: −${(n/5).toFixed(1)} from position fit</span>`).join('')}</div><p class="result-note">Five slot ratings ÷ 5. A native keeper protects your goalkeeping score; players out of position lose rating. No luck in the result.</p><button class="primary" id="rematch">Run it back ↻</button></div>`;$('results').hidden=false;$('rematch').onclick=()=>{reset();window.scrollTo({top:0,behavior:'smooth'});};if(scroll)$('results').scrollIntoView({behavior:'smooth',block:'start'});return {winner:winner===null?'draw':`Player ${winner+1}`,ratings:scores.map(s=>s.rating)};}
function readState(){return {firstBidder:state.firstBidder===null?null:state.firstBidder+1,mode:selectedMode,screen:$('home').hidden?'game':'home',poolSize:playerPool().length,phase:state.phase,auction:state.lot,footballer:state.current,bid:state.bid,leadingPlayer:state.leader===null?null:state.leader+1,turn:spotlight()===null?null:spotlight()+1,teams:state.teams.map((t,i)=>({player:i+1,budget:t.money,maxBid:maxBid(i),lineup:bestLineup(t.squad)}))};}
function selectMode(mode){if(!['current','prime'].includes(mode))throw Error('Unknown mode.');selectedMode=mode;document.querySelectorAll('[data-mode]').forEach(el=>{el.classList.toggle('selected',el.dataset.mode===mode);el.setAttribute('aria-pressed',String(el.dataset.mode===mode));});$('start-game').textContent='Start '+modeNames[mode].toLowerCase()+' →';$('selection-note').textContent=mode==='current'?'100 familiar names. Pick your favourites and outbid your mate.':'100 recognizable names. Greats, favourites and cult heroes.';}
function showHome(){$('home').hidden=false;$('game').hidden=true;$('mode-indicator').textContent='2 PLAYERS · ONE SCREEN';selectMode(selectedMode);window.scrollTo({top:0,behavior:'smooth'});}
function startGame(mode=selectedMode){if(!['current','prime'].includes(mode))throw Error('Choose current or prime.');reset(mode);$('home').hidden=true;$('game').hidden=false;$('mode-indicator').textContent=modeNames[mode].toUpperCase();window.scrollTo({top:0,behavior:'smooth'});return readState();}
document.querySelectorAll('[data-mode]').forEach(el=>el.onclick=()=>selectMode(el.dataset.mode));$('start-game').onclick=()=>startGame();
const ruleDialog=$('rules');$('rules-button').onclick=()=>ruleDialog.showModal();$('ratings-button').onclick=()=>$('rating-info').showModal();$('data-button').onclick=()=>$('data-info').showModal();document.querySelector('.close-data').onclick=()=>$('data-info').close();document.querySelector('.close-rating').onclick=()=>$('rating-info').close();document.querySelectorAll('#rules .close,#rules .close-rules').forEach(b=>b.onclick=()=>ruleDialog.close());$('reset-button').onclick=()=>{if($('home').hidden)$('restart').showModal();else showHome();};document.querySelector('.brand').onclick=e=>{e.preventDefault();if($('home').hidden)$('restart').showModal();else showHome();};document.querySelector('.cancel-reset').onclick=()=>$('restart').close();document.querySelector('.confirm-reset').onclick=()=>{$('restart').close();reset();showHome();};
$('current-pool-count').textContent=pools.current.length;$('prime-pool-count').textContent=pools.prime.length;reset();
showHome();
if(document.modelContext?.registerTool){const lifecycle=new AbortController();const definitions=[{name:'toss_first_bidder',description:'Flip a fair coin to decide who opens the first auction. Waits for the result.',inputSchema:{type:'object',properties:{},additionalProperties:false},execute:()=>toss()},{name:'start_football_game',description:'Start a fresh game in current or prime mode, clearing previous signings.',inputSchema:{type:'object',properties:{mode:{type:'string',enum:['current','prime']}},required:['mode'],additionalProperties:false},execute:input=>startGame(input?.mode)},{name:'read_football_auction',description:'Read current auction, budgets and best lineups.',inputSchema:{type:'object',properties:{},additionalProperties:false},execute:()=>readState(),readOnly:true},{name:'spin_footballer',description:'Spin and reveal the next footballer before a new auction. Waits for the reveal.',inputSchema:{type:'object',properties:{},additionalProperties:false},execute:()=>spin()},{name:'place_football_bid',description:'Bid for the player whose turn it is. Default raises by $1; amount can go up to their full balance. At zero budget, wait until paid bidding ends, then spin each free signing separately.',inputSchema:{type:'object',properties:{player:{type:'integer',enum:[1,2]},amount:{type:'integer',minimum:1,maximum:20}},required:['player'],additionalProperties:false},execute:input=>{if(!input||![1,2].includes(input.player))throw Error('Player must be 1 or 2.');return bid(input.player-1,input.amount);}},{name:'pass_football_bid',description:'Pass for this auction with no limit in either mode, including solo bidding. If there is a leading bidder, complete their signing.',inputSchema:{type:'object',properties:{player:{type:'integer',enum:[1,2]}},required:['player'],additionalProperties:false},execute:input=>{if(!input||![1,2].includes(input.player))throw Error('Player must be 1 or 2.');return pass(input.player-1);}}];for(const d of definitions){try{Promise.resolve(document.modelContext.registerTool({name:d.name,description:d.description,inputSchema:d.inputSchema,execute:d.execute,annotations:{readOnlyHint:!!d.readOnly,untrustedContentHint:false}},{signal:lifecycle.signal})).catch(()=>{});}catch{}}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
